const readline = require('readline');
const rl = readline.createInterface({ input: process.stdin, output: process.stdout });

rl.on('line', (line) => {
    const [n, m] = line.split(' ').map(Number);
    let maxFree = 0;
    const total = n * m;
    const dirs = [[0,0], [-1,0], [1,0], [0,-1], [0,1]];
    const cells = [];
    for (let i = 0; i < n; i++) {
        for (let j = 0; j < m; j++) {
            cells.push([i, j]);
        }
    }

    const dfs = (idx, occupied) => {
        if (idx === total) {
            maxFree = Math.max(maxFree, total - occupied.size);
            return;
        }
        const [x, y] = cells[idx];
        for (const [dx, dy] of dirs) {
            const nx = x + dx, ny = y + dy;
            if (nx >= 0 && nx < n && ny >= 0 && ny < m) {
                const key = nx * m + ny;
                occupied.add(key);
                dfs(idx + 1, occupied);
                occupied.delete(key);
            }
        }
    };

    dfs(0, new Set());
    console.log(maxFree);
    rl.close();
});
